# ! [doc = " The `ObligationForest` is a utility data structure used in trait"] # ! [doc = " matching to track the set of outstanding obligations (those not yet"] # ! [doc = " resolved to success or error). It also tracks the \"backtrace\" of each"] # ! [doc = " pending obligation (why we are trying to figure this out in the first"] # ! [doc = " place)."] # ! [doc = ""] # ! [doc = " ### External view"] # ! [doc = ""] # ! [doc = " `ObligationForest` supports two main public operations (there are a"] # ! [doc = " few others not discussed here):"] # ! [doc = ""] # ! [doc = " 1. Add a new root obligations (`register_obligation`)."] # ! [doc = " 2. Process the pending obligations (`process_obligations`)."] # ! [doc = ""] # ! [doc = " When a new obligation `N` is added, it becomes the root of an"] # ! [doc = " obligation tree. This tree can also carry some per-tree state `T`,"] # ! [doc = " which is given at the same time. This tree is a singleton to start, so"] # ! [doc = " `N` is both the root and the only leaf. Each time the"] # ! [doc = " `process_obligations` method is called, it will invoke its callback"] # ! [doc = " with every pending obligation (so that will include `N`, the first"] # ! [doc = " time). The callback also receives a (mutable) reference to the"] # ! [doc = " per-tree state `T`. The callback should process the obligation `O`"] # ! [doc = " that it is given and return a `ProcessResult`:"] # ! [doc = ""] # ! [doc = " - `Unchanged` -> ambiguous result. Obligation was neither a success"] # ! [doc = "   nor a failure. It is assumed that further attempts to process the"] # ! [doc = "   obligation will yield the same result unless something in the"] # ! [doc = "   surrounding environment changes."] # ! [doc = " - `Changed(C)` - the obligation was *shallowly successful*. The"] # ! [doc = "   vector `C` is a list of subobligations. The meaning of this is that"] # ! [doc = "   `O` was successful on the assumption that all the obligations in `C`"] # ! [doc = "   are also successful. Therefore, `O` is only considered a \"true\""] # ! [doc = "   success if `C` is empty. Otherwise, `O` is put into a suspended"] # ! [doc = "   state and the obligations in `C` become the new pending"] # ! [doc = "   obligations. They will be processed the next time you call"] # ! [doc = "   `process_obligations`."] # ! [doc = " - `Error(E)` -> obligation failed with error `E`. We will collect this"] # ! [doc = "   error and return it from `process_obligations`, along with the"] # ! [doc = "   \"backtrace\" of obligations (that is, the list of obligations up to"] # ! [doc = "   and including the root of the failed obligation). No further"] # ! [doc = "   obligations from that same tree will be processed, since the tree is"] # ! [doc = "   now considered to be in error."] # ! [doc = ""] # ! [doc = " When the call to `process_obligations` completes, you get back an `Outcome`,"] # ! [doc = " which includes two bits of information:"] # ! [doc = ""] # ! [doc = " - `completed`: a list of obligations where processing was fully"] # ! [doc = "   completed without error (meaning that all transitive subobligations"] # ! [doc = "   have also been completed). So, for example, if the callback from"] # ! [doc = "   `process_obligations` returns `Changed(C)` for some obligation `O`,"] # ! [doc = "   then `O` will be considered completed right away if `C` is the"] # ! [doc = "   empty vector. Otherwise it will only be considered completed once"] # ! [doc = "   all the obligations in `C` have been found completed."] # ! [doc = " - `errors`: a list of errors that occurred and associated backtraces"] # ! [doc = "   at the time of error, which can be used to give context to the user."] # ! [doc = ""] # ! [doc = " Upon completion, none of the existing obligations were *shallowly"] # ! [doc = " successful* (that is, no callback returned `Changed(_)`). This implies that"] # ! [doc = " all obligations were either errors or returned an ambiguous result."] # ! [doc = ""] # ! [doc = " ### Implementation details"] # ! [doc = ""] # ! [doc = " For the most part, comments specific to the implementation are in the"] # ! [doc = " code. This file only contains a very high-level overview. Basically,"] # ! [doc = " the forest is stored in a vector. Each element of the vector is a node"] # ! [doc = " in some tree. Each node in the vector has the index of its dependents,"] # ! [doc = " including the first dependent which is known as the parent. It also"] # ! [doc = " has a current state, described by `NodeState`. After each processing"] # ! [doc = " step, we compress the vector to remove completed and error nodes, which"] # ! [doc = " aren't needed anymore."] use split_decls_genesis :: ourprelude :: * ; use std :: cell :: Cell ; use std :: collections :: hash_map :: Entry ; use std :: fmt :: Debug ; use std :: hash ; use std :: marker :: PhantomData ; use thin_vec :: ThinVec ; use tracing :: debug ; use crate :: fx :: { FxHashMap , FxHashSet } ; mod graphviz ; #[cfg (test)] mod tests ; pub trait ForestObligation : Clone + Debug { type CacheKey : Clone + hash :: Hash + Eq + Debug ; #[doc = " Converts this `ForestObligation` suitable for use as a cache key."] #[doc = " If two distinct `ForestObligations`s return the same cache key,"] #[doc = " then it must be sound to use the result of processing one obligation"] #[doc = " (e.g. success for error) for the other obligation"] fn as_cache_key (& self) -> Self :: CacheKey ; } pub trait ObligationProcessor { type Obligation : ForestObligation ; type Error : Debug ; type OUT : OutcomeTrait < Obligation = Self :: Obligation , Error = Error < Self :: Obligation , Self :: Error > > ; #[doc = " Implementations can provide a fast-path to obligation-processing"] #[doc = " by counting the prefix of the passed iterator for which"] #[doc = " `needs_process_obligation` would return false."] fn skippable_obligations < 'a > (& 'a self , _it : impl Iterator < Item = & 'a Self :: Obligation > ,) -> usize { 0 } fn needs_process_obligation (& self , _obligation : & Self :: Obligation) -> bool ; fn process_obligation (& mut self , obligation : & mut Self :: Obligation ,) -> ProcessResult < Self :: Obligation , Self :: Error > ; #[doc = " As we do the cycle check, we invoke this callback when we"] #[doc = " encounter an actual cycle. `cycle` is an iterator that starts"] #[doc = " at the start of the cycle in the stack and walks **toward the"] #[doc = " top**."] #[doc = ""] #[doc = " In other words, if we had O1 which required O2 which required"] #[doc = " O3 which required O1, we would give an iterator yielding O1,"] #[doc = " O2, O3 (O1 is not yielded twice)."] fn process_backedge < 'c , I > (& mut self , cycle : I , _marker : PhantomData < & 'c Self :: Obligation > ,) -> Result < () , Self :: Error > where I : Clone + Iterator < Item = & 'c Self :: Obligation > ; } #[doc = " The result type used by `process_obligation`."] #[repr (C)] #[derive (Debug)] pub enum ProcessResult < O , E > { Unchanged , Changed (ThinVec < O >) , Error (E) , } #[derive (Clone , Copy , PartialEq , Eq , Hash , Debug)] struct ObligationTreeId (usize) ; pub struct ObligationForest < O : ForestObligation > { #[doc = " The list of obligations. In between calls to [Self::process_obligations],"] #[doc = " this list only contains nodes in the `Pending` or `Waiting` state."] #[doc = ""] #[doc = " `usize` indices are used here and throughout this module, rather than"] #[doc = " [`rustc_index::newtype_index!`] indices, because this code is hot enough"] #[doc = " that the `u32`-to-`usize` conversions that would be required are"] #[doc = " significant, and space considerations are not important."] nodes : Vec < Node < O > > , #[doc = " A cache of predicates that have been successfully completed."] done_cache : FxHashSet < O :: CacheKey > , #[doc = " A cache of the nodes in `nodes`, indexed by predicate. Unfortunately,"] #[doc = " its contents are not guaranteed to match those of `nodes`. See the"] #[doc = " comments in `Self::process_obligation` for details."] active_cache : FxHashMap < O :: CacheKey , usize > , #[doc = " A vector reused in [Self::compress()] and [Self::find_cycles_from_node()],"] #[doc = " to avoid allocating new vectors."] reused_node_vec : Vec < usize > , obligation_tree_id_generator : ObligationTreeIdGenerator , #[doc = " Per tree error cache. This is used to deduplicate errors,"] #[doc = " which is necessary to avoid trait resolution overflow in"] #[doc = " some cases."] #[doc = ""] #[doc = " See [this][details] for details."] #[doc = ""] #[doc = " [details]: https://github.com/rust-lang/rust/pull/53255#issuecomment-421184780"] error_cache : FxHashMap < ObligationTreeId , FxHashSet < O :: CacheKey > > , } #[derive (Debug)] struct Node < O > { obligation : O , state : Cell < NodeState > , #[doc = " Obligations that depend on this obligation for their completion. They"] #[doc = " must all be in a non-pending state."] dependents : Vec < usize > , #[doc = " If true, `dependents[0]` points to a \"parent\" node, which requires"] #[doc = " special treatment upon error but is otherwise treated the same."] #[doc = " (It would be more idiomatic to store the parent node in a separate"] #[doc = " `Option<usize>` field, but that slows down the common case of"] #[doc = " iterating over the parent and other descendants together.)"] has_parent : bool , #[doc = " Identifier of the obligation tree to which this node belongs."] obligation_tree_id : ObligationTreeId , } impl < O > Node < O > { fn new (parent : Option < usize > , obligation : O , obligation_tree_id : ObligationTreeId) -> Node < O > { Node { obligation , state : Cell :: new (NodeState :: Pending) , dependents : if let Some (parent_index) = parent { vec ! [parent_index] } else { vec ! [] } , has_parent : parent . is_some () , obligation_tree_id , } } } #[doc = " The state of one node in some tree within the forest. This represents the"] #[doc = " current state of processing for the obligation (of type `O`) associated"] #[doc = " with this node."] #[doc = ""] #[doc = " The non-`Error` state transitions are as follows."] #[doc = " ```text"] #[doc = " (Pre-creation)"] #[doc = "  |"] #[doc = "  |     register_obligation_at() (called by process_obligations() and"] #[doc = "  v                               from outside the crate)"] #[doc = " Pending"] #[doc = "  |"] #[doc = "  |     process_obligations()"] #[doc = "  v"] #[doc = " Success"] #[doc = "  |  ^"] #[doc = "  |  |  mark_successes()"] #[doc = "  |  v"] #[doc = "  |  Waiting"] #[doc = "  |"] #[doc = "  |     process_cycles()"] #[doc = "  v"] #[doc = " Done"] #[doc = "  |"] #[doc = "  |     compress()"] #[doc = "  v"] #[doc = " (Removed)"] #[doc = " ```"] #[doc = " The `Error` state can be introduced in several places, via `error_at()`."] #[doc = ""] #[doc = " Outside of `ObligationForest` methods, nodes should be either `Pending` or"] #[doc = " `Waiting`."] #[derive (Debug , Copy , Clone , PartialEq , Eq)] enum NodeState { #[doc = " This obligation has not yet been selected successfully. Cannot have"] #[doc = " subobligations."] Pending , #[doc = " This obligation was selected successfully, but may or may not have"] #[doc = " subobligations."] Success , #[doc = " This obligation was selected successfully, but it has a pending"] #[doc = " subobligation."] Waiting , #[doc = " This obligation, along with its subobligations, are complete, and will"] #[doc = " be removed in the next collection."] Done , #[doc = " This obligation was resolved to an error. It will be removed by the"] #[doc = " next compression step."] Error , } #[doc = " This trait allows us to have two different Outcome types:"] #[doc = "  - the normal one that does as little as possible"] #[doc = "  - one for tests that does some additional work and checking"] pub trait OutcomeTrait { type Error ; type Obligation ; fn new () -> Self ; fn record_completed (& mut self , outcome : & Self :: Obligation) ; fn record_error (& mut self , error : Self :: Error) ; } #[derive (Debug)] pub struct Outcome < O , E > { #[doc = " Backtrace of obligations that were found to be in error."] pub errors : Vec < Error < O , E > > , } impl < O , E > OutcomeTrait for Outcome < O , E > { type Error = Error < O , E > ; type Obligation = O ; fn new () -> Self { Self { errors : vec ! [] } } fn record_completed (& mut self , _outcome : & Self :: Obligation) { } fn record_error (& mut self , error : Self :: Error) { self . errors . push (error) } } #[derive (Debug , PartialEq , Eq)] pub struct Error < O , E > { pub error : E , pub backtrace : Vec < O > , } mod helper { use super :: * ; pub (super) type ObligationTreeIdGenerator = impl Iterator < Item = ObligationTreeId > ; impl < O : ForestObligation > ObligationForest < O > { #[define_opaque (ObligationTreeIdGenerator)] pub fn new () -> ObligationForest < O > { ObligationForest { nodes : vec ! [] , done_cache : Default :: default () , active_cache : Default :: default () , reused_node_vec : vec ! [] , obligation_tree_id_generator : (0 ..) . map (ObligationTreeId) , error_cache : Default :: default () , } } } } use helper :: * ; impl < O : ForestObligation > ObligationForest < O > { #[doc = " Returns the total number of nodes in the forest that have not"] #[doc = " yet been fully resolved."] pub fn len (& self) -> usize { self . nodes . len () } #[doc = " Registers an obligation."] pub fn register_obligation (& mut self , obligation : O) { let _ = self . register_obligation_at (obligation , None) ; } fn register_obligation_at (& mut self , obligation : O , parent : Option < usize >) -> Result < () , () > { let cache_key = obligation . as_cache_key () ; if self . done_cache . contains (& cache_key) { debug ! ("register_obligation_at: ignoring already done obligation: {:?}" , obligation) ; return Ok (()) ; } match self . active_cache . entry (cache_key) { Entry :: Occupied (o) => { let node = & mut self . nodes [* o . get ()] ; if let Some (parent_index) = parent { if ! node . dependents . contains (& parent_index) { node . dependents . push (parent_index) ; } } if let NodeState :: Error = node . state . get () { Err (()) } else { Ok (()) } } Entry :: Vacant (v) => { let obligation_tree_id = match parent { Some (parent_index) => self . nodes [parent_index] . obligation_tree_id , None => self . obligation_tree_id_generator . next () . unwrap () , } ; let already_failed = parent . is_some () && self . error_cache . get (& obligation_tree_id) . is_some_and (| errors | errors . contains (v . key ())) ; if already_failed { Err (()) } else { let new_index = self . nodes . len () ; v . insert (new_index) ; self . nodes . push (Node :: new (parent , obligation , obligation_tree_id)) ; Ok (()) } } } } #[doc = " Converts all remaining obligations to the given error."] pub fn to_errors < E : Clone > (& mut self , error : E) -> Vec < Error < O , E > > { let errors = self . nodes . iter () . enumerate () . filter (| (_index , node) | node . state . get () == NodeState :: Pending) . map (| (index , _node) | Error { error : error . clone () , backtrace : self . error_at (index) }) . collect () ; self . compress (| _ | assert ! (false)) ; errors } #[doc = " Returns the set of obligations that are in a pending state."] pub fn map_pending_obligations < P , F , R > (& self , f : F) -> R where F : Fn (& O) -> P , R : FromIterator < P > , { self . nodes . iter () . filter (| node | node . state . get () == NodeState :: Pending) . map (| node | f (& node . obligation)) . collect () } pub fn has_pending_obligations (& self) -> bool { self . nodes . iter () . any (| node | node . state . get () == NodeState :: Pending) } fn insert_into_error_cache (& mut self , index : usize) { let node = & self . nodes [index] ; self . error_cache . entry (node . obligation_tree_id) . or_default () . insert (node . obligation . as_cache_key ()) ; } #[doc = " Performs a fixpoint computation over the obligation list."] #[inline (never)] pub fn process_obligations < P > (& mut self , processor : & mut P) -> P :: OUT where P : ObligationProcessor < Obligation = O > , { let mut outcome = P :: OUT :: new () ; loop { let mut has_changed = false ; let mut index = processor . skippable_obligations (self . nodes . iter () . map (| n | & n . obligation)) ; while let Some (node) = self . nodes . get_mut (index) { if node . state . get () != NodeState :: Pending || ! processor . needs_process_obligation (& node . obligation) { index += 1 ; continue ; } match processor . process_obligation (& mut node . obligation) { ProcessResult :: Unchanged => { } ProcessResult :: Changed (children) => { has_changed = true ; node . state . set (NodeState :: Success) ; for child in children { let st = self . register_obligation_at (child , Some (index)) ; if let Err (()) = st { self . error_at (index) ; } } } ProcessResult :: Error (err) => { has_changed = true ; outcome . record_error (Error { error : err , backtrace : self . error_at (index) }) ; } } index += 1 ; } if ! has_changed { break ; } self . mark_successes () ; self . process_cycles (processor , & mut outcome) ; self . compress (| obl | outcome . record_completed (obl)) ; } outcome } #[doc = " Returns a vector of obligations for `p` and all of its"] #[doc = " ancestors, putting them into the error state in the process."] fn error_at (& self , mut index : usize) -> Vec < O > { let mut error_stack : Vec < usize > = vec ! [] ; let mut trace = vec ! [] ; loop { let node = & self . nodes [index] ; node . state . set (NodeState :: Error) ; trace . push (node . obligation . clone ()) ; if node . has_parent { error_stack . extend (node . dependents . iter () . skip (1)) ; index = node . dependents [0] ; } else { error_stack . extend (node . dependents . iter ()) ; break ; } } while let Some (index) = error_stack . pop () { let node = & self . nodes [index] ; if node . state . get () != NodeState :: Error { node . state . set (NodeState :: Error) ; error_stack . extend (node . dependents . iter ()) ; } } trace } #[doc = " Mark all `Waiting` nodes as `Success`, except those that depend on a"] #[doc = " pending node."] fn mark_successes (& self) { for node in & self . nodes { if node . state . get () == NodeState :: Waiting { node . state . set (NodeState :: Success) ; } } for node in & self . nodes { if node . state . get () == NodeState :: Pending { self . inlined_mark_dependents_as_waiting (node) ; } } } #[inline (always)] fn inlined_mark_dependents_as_waiting (& self , node : & Node < O >) { for & index in node . dependents . iter () { let node = & self . nodes [index] ; let state = node . state . get () ; if state == NodeState :: Success { self . uninlined_mark_dependents_as_waiting (node) ; } else { debug_assert ! (state == NodeState :: Waiting || state == NodeState :: Error) } } } #[inline (never)] fn uninlined_mark_dependents_as_waiting (& self , node : & Node < O >) { node . state . set (NodeState :: Waiting) ; self . inlined_mark_dependents_as_waiting (node) } #[doc = " Report cycles between all `Success` nodes, and convert all `Success`"] #[doc = " nodes to `Done`. This must be called after `mark_successes`."] fn process_cycles < P > (& mut self , processor : & mut P , outcome : & mut P :: OUT) where P : ObligationProcessor < Obligation = O > , { let mut stack = std :: mem :: take (& mut self . reused_node_vec) ; for (index , node) in self . nodes . iter () . enumerate () { if node . state . get () == NodeState :: Success { self . find_cycles_from_node (& mut stack , processor , index , outcome) ; } } debug_assert ! (stack . is_empty ()) ; self . reused_node_vec = stack ; } fn find_cycles_from_node < P > (& self , stack : & mut Vec < usize > , processor : & mut P , index : usize , outcome : & mut P :: OUT ,) where P : ObligationProcessor < Obligation = O > , { let node = & self . nodes [index] ; if node . state . get () == NodeState :: Success { match stack . iter () . rposition (| & n | n == index) { None => { stack . push (index) ; for & dep_index in node . dependents . iter () { self . find_cycles_from_node (stack , processor , dep_index , outcome) ; } stack . pop () ; node . state . set (NodeState :: Done) ; } Some (rpos) => { let result = processor . process_backedge (stack [rpos ..] . iter () . map (| & i | & self . nodes [i] . obligation) , PhantomData ,) ; if let Err (err) = result { outcome . record_error (Error { error : err , backtrace : self . error_at (index) }) ; } } } } } #[doc = " Compresses the vector, removing all popped nodes. This adjusts the"] #[doc = " indices and hence invalidates any outstanding indices. `process_cycles`"] #[doc = " must be run beforehand to remove any cycles on `Success` nodes."] #[inline (never)] fn compress (& mut self , mut outcome_cb : impl FnMut (& O)) { let orig_nodes_len = self . nodes . len () ; let mut node_rewrites : Vec < _ > = std :: mem :: take (& mut self . reused_node_vec) ; debug_assert ! (node_rewrites . is_empty ()) ; node_rewrites . extend (0 .. orig_nodes_len) ; let mut dead_nodes = 0 ; for index in 0 .. orig_nodes_len { let node = & self . nodes [index] ; match node . state . get () { NodeState :: Pending | NodeState :: Waiting => { if dead_nodes > 0 { self . nodes . swap (index , index - dead_nodes) ; node_rewrites [index] -= dead_nodes ; } } NodeState :: Done => { let cache_key = node . obligation . as_cache_key () ; self . active_cache . remove (& cache_key) ; self . done_cache . insert (cache_key) ; outcome_cb (& node . obligation) ; node_rewrites [index] = orig_nodes_len ; dead_nodes += 1 ; } NodeState :: Error => { self . active_cache . remove (& node . obligation . as_cache_key ()) ; self . insert_into_error_cache (index) ; node_rewrites [index] = orig_nodes_len ; dead_nodes += 1 ; } NodeState :: Success => unreachable ! () , } } if dead_nodes > 0 { self . nodes . truncate (orig_nodes_len - dead_nodes) ; self . apply_rewrites (& node_rewrites) ; } node_rewrites . truncate (0) ; self . reused_node_vec = node_rewrites ; } #[inline (never)] fn apply_rewrites (& mut self , node_rewrites : & [usize]) { let orig_nodes_len = node_rewrites . len () ; for node in & mut self . nodes { let mut i = 0 ; while let Some (dependent) = node . dependents . get_mut (i) { let new_index = node_rewrites [* dependent] ; if new_index >= orig_nodes_len { node . dependents . swap_remove (i) ; if i == 0 && node . has_parent { node . has_parent = false ; } } else { * dependent = new_index ; i += 1 ; } } } self . active_cache . retain (| _predicate , index | { let new_index = node_rewrites [* index] ; if new_index >= orig_nodes_len { false } else { * index = new_index ; true } }) ; } }